package com.cenedu.backend.ai.problem.render; import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.SemanticResolvedValue; import java.util.*; public final class NumberLineSvgRenderer { public String render(NumberLineDiagramSpecV1 s){return render(s,Map.of());} public String render(NumberLineDiagramSpecV1 s,Map<String,SemanticResolvedValue> values){int p=s.viewport().padding(),y=s.viewport().height()/2,end=s.viewport().width()-p;double min=num(values,s.minKey(),0),max=num(values,s.maxKey(),10),range=max-min;var b=new StringBuilder("<line x1=\"").append(p).append("\" y1=\"").append(y).append("\" x2=\"").append(end).append("\" y2=\"").append(y).append("\" stroke=\"#000000\"/>");for(var point:s.points()){int x=(int)(p+(num(values,point.positionKey(),min)-min)/(range==0?1:range)*(end-p));b.append("<circle cx=\"").append(x).append("\" cy=\"").append(y).append("\" r=\"5\" fill=\"").append(point.marker()==PointMarker.CLOSED_CIRCLE?"#000000":"#FFFFFF").append("\" stroke=\"#000000\"/>");}return b.toString();} private double num(Map<String,SemanticResolvedValue> v,String k,double d){try{return Double.parseDouble(v.get(k).canonicalValue());}catch(Exception e){return d;}} }
